// These tests pin what a script sees from the integer methods of a buffer and
// a reader: every value, and the whole text of every refusal. Each script runs
// through the methods, and its result is compared with a golden file written
// from the code as it was before change C38c.
//
// Update the golden table only on purpose: go test -run TestPin -update.
//
// Revisions:
//   - 2026-11-04 06:52: initial creation
//   - 2026-11-06 22:37: revision history added (C90)
//   - 2026-11-09 11:34: the golden is the GOLDEN table at the end of this file (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
package tests

import (
	"flag"
	"fmt"
	"go/format"
	"os"
	"strconv"
	"strings"
	"testing"
	"unicode/utf8"
)

const (
	// SOURCE is this file, which holds the GOLDEN table. A test runs in the
	// directory of its package, so the bare name finds the file.
	//
	// Revisions:
	//   - 2026-11-09 11:34: initial creation (C114, Q282)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	SOURCE = "pin_test.go"

	// FAILED marks a refusal in a golden row, and VALUE a result.
	//
	// Revisions:
	//   - 2026-11-04 06:52: initial creation
	//   - 2026-11-06 22:37: revision history added (C90)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	FAILED = "error: "
	VALUE  = "value: "
)

var (
	// UPDATE asks TestPin to write the GOLDEN table.
	//
	// Revisions:
	//   - 2026-11-09 17:05: the flag writes the table, not a file (C114, Q282)
	//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
	UPDATE = flag.Bool(
		"update",
		false,
		"write the GOLDEN table of TestPin",
	)
)

// _Pinned is every script the pin test runs, in a fixed order.
//
// Revisions:
//   - 2026-11-04 00:51: initial creation (C38c)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Pinned() []string {
	var (
		rows    []string
		numbers = []string{
			`0`,
			`1`,
			`-1`,
			`127`,
			`128`,
			`-128`,
			`-129`,
			`255`,
			`256`,
			`32767`,
			`32768`,
			`-32768`,
			`-32769`,
			`65535`,
			`65536`,
			`2147483647`,
			`2147483648`,
			`-2147483648`,
			`-2147483649`,
			`4294967295`,
			`4294967296`,
			`9223372036854775807`,
			`9223372036854775808`,
			`-9223372036854775808`,
			`-9223372036854775809`,
			`18446744073709551615`,
			`18446744073709551616`,
			`10 ** 400`,
		}
		fixed = []string{
			"write_uint8",
			"write_uint16",
			"write_uint32",
			"write_uint64",
			"write_int8",
			"write_int16",
			"write_int32",
			"write_int64",
		}
		orders = []string{
			``,
			`, "big"`,
			`, "little"`,
			`, "zz"`,
		}
		widths = []string{
			`0`,
			`-1`,
			`1`,
			`3`,
			`8`,
			`9`,
		}
		reads = []string{
			"read_uint8",
			"read_uint16",
			"read_uint32",
			"read_uint64",
			"read_int8",
			"read_int16",
			"read_int32",
			"read_int64",
		}
		datas = []string{
			`b""`,
			`b"\x00\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\x01\x02\x03\x04\x05\x06\x07\x08"`,
			`b"\x7f\xff\xff\xff\xff\xff\xff\xff"`,
			`b"\x80\x00\x00\x00\x00\x00\x00\x00"`,
			`b"\xff\xff\xff\xff\xff\xff\xff\xff"`,
		}
	)

	for _, number := range numbers {
		for _, method := range fixed {
			for _, order := range orders {
				rows = append(
					rows,
					"b = buf.new(); b.write_uint8(7); b."+method+"("+
						number+order+"); out = b.bytes()",
				)
			}
		}

		for _, method := range []string{
			"write_uint",
			"write_int",
		} {
			for _, width := range widths {
				for _, order := range orders {
					rows = append(
						rows,
						"b = buf.new(); b."+method+"("+number+", "+width+
							order+"); out = b.bytes()",
					)
				}
			}
		}
	}

	for _, data := range datas {
		for _, method := range reads {
			for _, order := range orders {
				rows = append(
					rows,
					"r = buf.reader("+data+"); out = [r."+method+"("+
						strings.TrimPrefix(
							order,
							", ",
						)+"), r.read_bytes(0), len(r)]",
				)
			}
		}

		for _, method := range []string{
			"read_uint",
			"read_int",
		} {
			for _, width := range widths {
				for _, order := range orders {
					rows = append(
						rows,
						"r = buf.reader("+data+"); out = [r."+method+
							"("+width+order+"), len(r)]",
					)
				}
			}
		}
	}

	return append(
		rows,
		`b = buf.new(); b.write_uint8()`,
		`b = buf.new(); b.write_uint8(1, "big", 3)`,
		`b = buf.new(); b.write_uint8(1, order = "little"); out = b.bytes()`,
		`b = buf.new(); b.write_uint8(n = 1)`,
		`b = buf.new(); b.write_uint8("1")`,
		`b = buf.new(); b.write_uint8(1.5)`,
		`b = buf.new(); b.write_uint8(1, 2)`,
		`b = buf.new(); b.write_uint8(1, None)`,
		`b = buf.new(); b.write_uint(1)`,
		`b = buf.new(); b.write_uint(1, "2")`,
		`b = buf.new(); b.write_uint(1, 2, 3)`,
		`b = buf.new(); b.write_uint(1, 2, "big", 4)`,
		`b = buf.new(); b.write_uint(1, 2, order = "little"); out = b.bytes()`,
		`b = buf.new(); b.write_uint(n = 1, width = 2); out = b.bytes()`,
		`b = buf.new(); b.write_int(1, 9223372036854775808)`,
		`r = buf.reader(b"\x01"); r.read_uint8(1)`,
		`r = buf.reader(b"\x01"); r.read_uint8("big", 2)`,
		`r = buf.reader(b"\x01"); r.read_uint8(order = "big")`,
		`r = buf.reader(b"\x01"); r.read_uint()`,
		`r = buf.reader(b"\x01"); r.read_uint("1")`,
		`r = buf.reader(b"\x01"); r.read_uint(2)`,
		`r = buf.reader(b"\x01\x02"); out = [r.read_uint(1), r.read_uint(1)]`,
		`r = buf.reader(b"\x01\x02"); out = [r.read_uint(2, "little"), len(r)]`,
		`r = buf.reader(b"\x01"); r.read_int8(); r.read_int8()`,
		`r = buf.reader(b"\x01"); out = type(r.read_uint8())`,
	)
}

// _Shown runs script, and says what it left in out: its String form, or the
// whole text of the refusal.
//
// Revisions:
//   - 2026-11-04 00:51: initial creation (C38c)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Shown(
	t *testing.T,
	script string,
) string {
	t.Helper()

	out, err := _Run(
		t,
		script,
	)
	if err != nil {
		return FAILED + err.Error()
	}

	return VALUE + out
}

// _Golden reads the GOLDEN table as a map from script to result.
//
// Revisions:
//   - 2026-11-04 00:51: initial creation (C38c)
//   - 2026-11-09 11:34: reads the GOLDEN table, not a file (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Golden() map[string]string {
	rows := make(
		map[string]string,
		len(GOLDEN),
	)

	for _, row := range GOLDEN {
		rows[row.expr] = row.want
	}

	return rows
}

// _Raw says whether text can stand in a Go raw string unchanged: it holds no
// backtick, no carriage return (the compiler drops it from a raw string), no
// byte-order mark, no invalid UTF-8 and no control character but a tab and a
// newline.
//
// Revisions:
//   - 2026-11-09 11:34: initial creation (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Raw(text string) bool {
	if !utf8.ValidString(text) {
		return false
	}

	for _, r := range text {
		if r == '`' || r == '\r' || r == '\uFEFF' || r == 0x7f ||
			(r < ' ' && r != '\t' && r != '\n') {
			return false
		}
	}

	return true
}

// _Literal is the Go source of text: a raw string when _Raw allows, else a
// quoted string.
//
// Revisions:
//   - 2026-11-09 11:34: initial creation (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Literal(text string) string {
	if _Raw(text) {
		return "`" + text + "`"
	}

	return strconv.Quote(text)
}

// _Rewrite replaces the GOLDEN table in SOURCE with rows. It changes only the
// text from the var line of the table to the END marker: the doc comment above
// the var and every byte outside the two markers stay as they are. It formats
// the new table with go/format.
//
// Revisions:
//   - 2026-11-09 11:34: initial creation (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func _Rewrite(
	t *testing.T,
	rows []struct{ expr, want string },
) {
	t.Helper()

	var table strings.Builder

	table.WriteString("var (\n\tGOLDEN = []struct{ expr, want string }{\n")

	for _, row := range rows {
		fmt.Fprintf(
			&table,
			"{%s, %s},\n",
			_Literal(row.expr),
			_Literal(row.want),
		)
	}

	table.WriteString("\t}\n)\n")

	formatted, err := format.Source([]byte(table.String()))
	if err != nil {
		t.Fatal(err)
	}

	raw, err := os.ReadFile(SOURCE)
	if err != nil {
		t.Fatal(err)
	}

	// The last markers in the file are the real ones; the strings above hold
	// the same text.
	var (
		source = string(raw)
		begin  = strings.LastIndex(
			source,
			"\n// BEGIN GOLDEN:",
		)
		end = strings.LastIndex(
			source,
			"\n// END GOLDEN",
		)
	)

	if begin < 0 || end < begin {
		t.Fatalf(
			"%s has no GOLDEN markers",
			SOURCE,
		)
	}

	start := strings.Index(
		source[begin:end],
		"\nvar (\n\tGOLDEN = ",
	)
	if start < 0 {
		t.Fatalf(
			"%s has no GOLDEN table",
			SOURCE,
		)
	}

	start += begin + 1

	err = os.WriteFile(
		SOURCE,
		[]byte(source[:start]+string(formatted)+"\n"+source[end+1:]),
		0o644,
	)
	if err != nil {
		t.Fatal(err)
	}
}

// TestPin_IntegerMethodsGiveTheSameResults runs every pinned script and wants
// the result in the golden file, byte for byte, or with -update writes the
// file.
//
// Success: every row passes, and the table holds a row for each script.
//
// Revisions:
//   - 2026-11-04 00:51: initial creation (C38c)
//   - 2026-11-09 11:34: the golden is a table in this file (C114, Q282)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
func TestPin_IntegerMethodsGiveTheSameResults(t *testing.T) {
	scripts := _Pinned()

	if *UPDATE {
		rows := make(
			[]struct{ expr, want string },
			0,
			len(scripts),
		)

		for _, script := range scripts {
			rows = append(
				rows,
				struct{ expr, want string }{
					script,
					_Shown(
						t,
						script,
					),
				},
			)
		}

		_Rewrite(
			t,
			rows,
		)

		return
	}

	golden := _Golden()

	if len(golden) != len(scripts) {
		t.Fatalf(
			"the GOLDEN table holds %d rows, the test runs %d",
			len(golden),
			len(scripts),
		)
	}

	for _, script := range scripts {
		t.Run(
			script,
			func(t *testing.T) {
				want, found := golden[script]
				if !found {
					t.Fatalf(
						"no golden row for %s",
						script,
					)
				}

				got := _Shown(
					t,
					script,
				)
				if got != want {
					t.Fatalf(
						"%s gave %s, want %s",
						script,
						got,
						want,
					)
				}
			},
		)
	}
}

// BEGIN GOLDEN: written by go test -run TestPin -update; edit by hand only to review.

// GOLDEN is the expected result of every pinned script, one row each: the script and
// the String form of its value or the whole text of its refusal, marked by
// VALUE or FAILED. The rows keep the order of _Pinned.
//
// Revisions:
//   - 2026-11-04 06:52: initial creation
//   - 2026-11-06 22:37: revision history added (C90)
//   - 2026-11-09 20:19: the table replaces testdata/pin.golden, in a var group under one nolint:lll (C114, Q282, Q290)
//   - 2026-11-10 00:25: moved to tests/ (C120a, Q311)
